import React from "react";
import ReactDOM from "react-dom/client";
import { RouterProvider, createRouter } from "@tanstack/react-router";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
// @ts-ignore - auto-generated by TanStack Router plugin
import { routeTree } from "./routeTree.gen";
import "./index.css";

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: false,
      retry: 1,
    },
  },
});

const router = createRouter({
  routeTree,
  // Production is served under `/grocery/` (see `base` in vite.config.ts and
  // `location ^~ /grocery/` in scripts/nginx.conf). TanStack Router does not
  // read Vite's BASE_URL on its own, so without this every route resolves
  // against `/` and the app renders "Not Found" at `/grocery/*`.
  // Dev keeps `base: "/"`, so the stripped value is an empty string.
  basepath: import.meta.env.BASE_URL.replace(/\/$/, ""),
  context: {
    queryClient,
  },
});

declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router;
  }
}

ReactDOM.createRoot(document.getElementById("root")!).render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <RouterProvider router={router} />
    </QueryClientProvider>
  </React.StrictMode>
);
